"""Assemble independent lineage conclusions and final hashes; no model evaluation."""
from pathlib import Path
import sys,json,hashlib,datetime as dt,platform
import pandas as pd
import numpy as np
OUT=Path(__file__).resolve().parent;ROOT=OUT.parents[4];NOW=dt.datetime.now(dt.timezone.utc).isoformat()
def jr(p):return json.loads(p.read_text(encoding='utf-8-sig'))
def wj(n,v):(OUT/n).write_text(json.dumps(v,ensure_ascii=False,indent=2),encoding='utf-8')
def sha(p):
    h=hashlib.sha256()
    with p.open('rb') as f:
        for b in iter(lambda:f.read(4194304),b''):h.update(b)
    return h.hexdigest()
base=jr(OUT/'validation.json');supp=jr(OUT/'supplement_validation.json')
checks=base['checks']+supp['checks']
for c in checks:
    if c['item']=='description-specific_count_consistency':
        c['scope']='Five nonterminal ball rows and one nonterminal swinging_strike row fail the expected next-count rule. Source/measurement exceptions, not raw-to-processed transformation mismatches. Existing broad delta checker permits unchanged counts and does not detect these.'
        c['review_text_correction']='The supplement initially described all six as ball; correct composition is 5 ball + 1 swinging_strike. Numeric exception counts and row files unchanged.'
wj('final_validation.json',{'finalized_at_utc':NOW,'scope':base['scope'],'tolerances':base['tolerances'],'summary':base['summary'],'checks':checks,'review_text_correction':'Corrected only exception composition wording in this consolidated file; original supplement code/results retained.','overall_source_reconstruction':'PASS: all full-source raw-to-prepared-to-five-score comparisons match','overall_source_truth':'NOT_VERIFIABLE for six description-count exceptions and latent intent/perception','model_fitting':'NOT_RUN; no fitting or model prediction regeneration in lineage work'})
